-- composition of rule kernels column_lifetime x cte_inlining (duckdb), template product
SELECT count(*) FROM (WITH RECURSIVE rc(c0) AS (SELECT 1 UNION ALL SELECT r.c0 + 1 FROM rc AS r WHERE r.c0 < 5) SELECT TRUE AS c0, [1, 2, 3]::int[] AS c1, 1.5::numeric AS c2, LEAST (LEAST (1.5::numeric, (SELECT MAX (100.0::numeric) FROM v0 AS a2 WHERE COALESCE (COALESCE ((a1.c0 BETWEEN 16 AND 3), TRUE), FALSE))), NULL::numeric) AS c3 FROM v0 AS a1) AS ka CROSS JOIN (WITH RECURSIVE rc(c0) AS (SELECT 1 UNION ALL SELECT r.c0 + 1 FROM rc AS r WHERE r.c0 < 100) SELECT []::text[] AS c0, 100.0::float8 AS c1, '-3 hours'::interval AS c2 UNION ALL SELECT ARRAY['1'::text] AS c0, (-1.5)::float8 AS c1, MIN ('0'::interval) OVER (PARTITION BY 1000::bigint, 'A'::text) AS c2 FROM (SELECT FALSE AS c0) AS a1) AS kb;
